    public static void drawShape(BlockPos blockPos, VoxelShape voxelShape, int color, float width) {
        drawShape(blockPos, voxelShape, color, width, true, false);
    }

    public static void drawShape(BlockPos blockPos, VoxelShape voxelShape, int color, float width, boolean fill, boolean depth) {
        List<Box> boxes = SHAPE_BOXES.computeIfAbsent(voxelShape, VoxelShape::getBoundingBoxes);
        boxes.forEach(box -> {
            Box offsetBox = box.offset(blockPos);
            if (ProjectionUtil.canSee(offsetBox)) drawBox(offsetBox, color, width, true, fill, depth);
        });
    }

    public static void drawShapeAlternative(BlockPos blockPos, VoxelShape voxelShape, int color, float width, boolean fill, boolean depth) {
        Vec3d vec3d = Vec3d.of(blockPos);
        if (ProjectionUtil.canSee(new Box(blockPos))) {
            Pair<List<Box>, List<Line>> pair = SHAPE_OUTLINES.computeIfAbsent(voxelShape, shape -> {
                List<Line> lines = new ArrayList<>();
                shape.forEachEdge((minX, minY, minZ, maxX, maxY, maxZ) -> lines.add(new Line(null, new Vec3d(minX, minY, minZ), new Vec3d(maxX, maxY, maxZ), 0, 0, 0)));
                return new Pair<>(shape.getBoundingBoxes(), lines);
            });
            if (fill) pair.getLeft().forEach(box -> drawBox(box.offset(vec3d), color, width, false, true, depth));
            pair.getRight().forEach(line -> drawLineSmooth(line.start.add(vec3d), line.end.add(vec3d), color, width, depth));
        }
    }

    public static void drawShapeHatched(BlockPos blockPos, VoxelShape voxelShape, int color, float width, boolean depth) {
        List<Box> boxes = SHAPE_BOXES.computeIfAbsent(voxelShape, VoxelShape::getBoundingBoxes);
        boxes.forEach(box -> {
            Box offsetBox = box.offset(blockPos);
            if (ProjectionUtil.canSee(offsetBox)) drawHatchedBox(offsetBox, color, width, depth);
        });
    }

    public static void drawBox(Box box, int color, float width) {
        drawBox(box, color, width, true, true, false);
    }

    public static void drawBox(Box box, int color, float width, boolean line, boolean fill, boolean depth) {
        drawBox(null, box, color, width, line, fill, depth);
    }

    public static void drawBox(MatrixStack.Entry entry, Box box, int color, float width, boolean line, boolean fill, boolean depth) {
        box = box.expand(0.001);
        double x1 = box.minX;
        double y1 = box.minY;
        double z1 = box.minZ;
        double x2 = box.maxX;
        double y2 = box.maxY;
        double z2 = box.maxZ;
        if (fill) {
            int fillColor = ColorUtil.multAlpha(color, 0.1F);
            drawQuad(entry, new Vec3d(x1, y1, z1), new Vec3d(x2, y1, z1), new Vec3d(x2, y1, z2), new Vec3d(x1, y1, z2), fillColor, depth);
            drawQuad(entry, new Vec3d(x1, y1, z1), new Vec3d(x1, y2, z1), new Vec3d(x2, y2, z1), new Vec3d(x2, y1, z1), fillColor, depth);
            drawQuad(entry, new Vec3d(x2, y1, z1), new Vec3d(x2, y2, z1), new Vec3d(x2, y2, z2), new Vec3d(x2, y1, z2), fillColor, depth);
            drawQuad(entry, new Vec3d(x1, y1, z2), new Vec3d(x2, y1, z2), new Vec3d(x2, y2, z2), new Vec3d(x1, y2, z2), fillColor, depth);
            drawQuad(entry, new Vec3d(x1, y1, z1), new Vec3d(x1, y1, z2), new Vec3d(x1, y2, z2), new Vec3d(x1, y2, z1), fillColor, depth);
            drawQuad(entry, new Vec3d(x1, y2, z1), new Vec3d(x1, y2, z2), new Vec3d(x2, y2, z2), new Vec3d(x2, y2, z1), fillColor, depth);
        }
        if (line) {
            drawLine(entry, x1, y1, z1, x2, y1, z1, color, width, depth);
            drawLine(entry, x2, y1, z1, x2, y1, z2, color, width, depth);
            drawLine(entry, x2, y1, z2, x1, y1, z2, color, width, depth);
            drawLine(entry, x1, y1, z2, x1, y1, z1, color, width, depth);
            drawLine(entry, x1, y1, z2, x1, y2, z2, color, width, depth);
            drawLine(entry, x1, y1, z1, x1, y2, z1, color, width, depth);
            drawLine(entry, x2, y1, z2, x2, y2, z2, color, width, depth);
            drawLine(entry, x2, y1, z1, x2, y2, z1, color, width, depth);
            drawLine(entry, x1, y2, z1, x2, y2, z1, color, width, depth);
            drawLine(entry, x2, y2, z1, x2, y2, z2, color, width, depth);
            drawLine(entry, x2, y2, z2, x1, y2, z2, color, width, depth);
            drawLine(entry, x1, y2, z2, x1, y2, z1, color, width, depth);
        }
    }

    public static void drawHatchedBox(Box box, int color, float width, boolean depth) {
        box = box.expand(0.001);
        double x1 = box.minX;
        double y1 = box.minY;
        double z1 = box.minZ;
        double x2 = box.maxX;
        double y2 = box.maxY;
        double z2 = box.maxZ;
        int outlineColor = ColorUtil.multAlpha(color, 0.9F);
        int hatchColor = ColorUtil.multAlpha(color, 0.45F);
        drawBox(box, outlineColor, width, true, false, depth);
        drawHatchedFace(new Vec3d(x1, y2, z1), new Vec3d(x2 - x1, 0.0, 0.0), new Vec3d(0.0, 0.0, z2 - z1), hatchColor, width, depth);
        drawHatchedFace(new Vec3d(x1, y1, z1), new Vec3d(x2 - x1, 0.0, 0.0), new Vec3d(0.0, y2 - y1, 0.0), hatchColor, width, depth);
        drawHatchedFace(new Vec3d(x1, y1, z2), new Vec3d(x2 - x1, 0.0, 0.0), new Vec3d(0.0, y2 - y1, 0.0), hatchColor, width, depth);
        drawHatchedFace(new Vec3d(x1, y1, z1), new Vec3d(0.0, y2 - y1, 0.0), new Vec3d(0.0, 0.0, z2 - z1), hatchColor, width, depth);
        drawHatchedFace(new Vec3d(x2, y1, z1), new Vec3d(0.0, y2 - y1, 0.0), new Vec3d(0.0, 0.0, z2 - z1), hatchColor, width, depth);
    }

    private static void drawHatchedFace(Vec3d origin, Vec3d u, Vec3d v, int color, float width, boolean depth) {
        double uLength = u.length();
        double vLength = v.length();
        if (uLength <= 1.0E-4 || vLength <= 1.0E-4) {
            return;
        }
        Vec3d uDir = u.multiply(1.0 / uLength);
        Vec3d vDir = v.multiply(1.0 / vLength);
        double step = Math.max(0.08, Math.min(Math.min(uLength, vLength) / 3.0, 0.2));
        double maxOffset = uLength + vLength;
        for (double offset = 0.0; offset <= maxOffset + 1.0E-4; offset += step) {
            double startU = Math.min(offset, uLength);
            double startV = Math.max(0.0, offset - uLength);
            double endU = Math.max(0.0, offset - vLength);
            double endV = Math.min(offset, vLength);
            Vec3d start = origin.add(uDir.multiply(startU)).add(vDir.multiply(startV));
            Vec3d end = origin.add(uDir.multiply(endU)).add(vDir.multiply(endV));
            drawLine(start, end, color, width, depth);
        }
    }

    public static void vertexLine(MatrixStack matrices, VertexConsumer buffer, Vec3d start, Vec3d end, int startColor, int endColor) {
        vertexLine(matrices.peek(), buffer, start.toVector3f(), end.toVector3f(), startColor, endColor);
    }

    public static void vertexLine(MatrixStack.Entry entry, VertexConsumer buffer, Vector3f start, Vector3f end, int startColor, int endColor) {
        if (entry == null) entry = lastWorldSpaceMatrix;
        Vector3f vec = getNormal(start, end);
        buffer.vertex(entry, start).color(startColor).normal(entry, vec);
        buffer.vertex(entry, end).color(endColor).normal(entry, vec);
    }

    public static void vertexQuad(MatrixStack.Entry entry, VertexConsumer buffer, Vec3d vec1, Vec3d vec2, Vec3d vec3, Vec3d vec4, int color) {
        vertexQuad(entry, buffer, vec1.toVector3f(), vec2.toVector3f(), vec3.toVector3f(), vec4.toVector3f(), color);
    }

    public static void vertexQuad(MatrixStack.Entry entry, VertexConsumer buffer, Vector3f vec1, Vector3f vec2, Vector3f vec3, Vector3f vec4, int color) {
        if (entry == null) entry = lastWorldSpaceMatrix;
        buffer.vertex(entry, vec1).color(color);
        buffer.vertex(entry, vec2).color(color);
        buffer.vertex(entry, vec3).color(color);
        buffer.vertex(entry, vec4).color(color);
    }

    public static void quadTexture(MatrixStack.Entry entry, BufferBuilder buffer, float x, float y, float width, float height, Vector4i color) {
        buffer.vertex(entry, x, y + height, 0).texture(0, 0).color(color.x);
        buffer.vertex(entry, x + width, y + height, 0).texture(0, 1).color(color.y);
        buffer.vertex(entry, x + width, y, 0).texture(1, 1).color(color.w);
        buffer.vertex(entry, x, y, 0).texture(1, 0).color(color.z);
    }

    @NotNull
    public static Vector3f getNormal(Vector3f start, Vector3f end) {
        Vector3f normal = new Vector3f(start).sub(end);
        float sqrt = MathHelper.sqrt(normal.lengthSquared());
        return normal.div(sqrt);
    }

    public static void drawCube(LivingEntity lastTarget, float anim, float red, boolean throughWalls, int baseEspColor, float fixedRotation, float hitShrink) {
        float baseSize = Float.isNaN(fixedRotation) ? 2.2F - anim : 1.2F;
        float size = Math.max(baseSize * (1.0F - hitShrink), baseSize * 0.65F);
        Camera camera = mc.getEntityRenderDispatcher().camera;
        Vec3d vec = getInterpolatedBoxCenter(lastTarget);
        MatrixStack matrix = new MatrixStack();
        matrix.push();
        matrix.multiplyPositionMatrix(lastWorldSpaceMatrix.getPositionMatrix());
        matrix.translate(vec.x, vec.y, vec.z);
        matrix.multiply(camera.getRotation());
        matrix.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(Float.isNaN(fixedRotation) ? MathUtil.interpolate(prevEspValue, espValue) : fixedRotation));
        MatrixStack.Entry entry = matrix.peek().copy();
        float pulse = 0.85F + 0.15F * (float) Math.sin(System.currentTimeMillis() * 0.0045F);
        int saturated = boost(ColorUtil.multRed(baseEspColor, 1 + red * 10), 1.32F);
        int core = ColorUtil.multAlpha(saturated, anim);
        int glowInner = ColorUtil.multAlpha(ColorUtil.overCol(saturated, ColorUtil.WHITE, 0.18F), anim * 0.34F * pulse);
        int glowOuter = ColorUtil.multAlpha(saturated, anim * 0.16F * pulse);
        int hot = ColorUtil.multAlpha(ColorUtil.overCol(saturated, ColorUtil.WHITE, 0.55F), anim * 0.4F * pulse);
        float glowSize = size * 1.7F;
        boolean depth = !throughWalls;
        Render3DUtil.drawTexture(entry, bloom, -glowSize / 2, -glowSize / 2, glowSize, glowSize, new Vector4i(glowOuter, glowOuter, glowOuter, glowOuter), depth);
        Render3DUtil.drawTexture(entry, bloom, -glowSize * 0.36F, -glowSize * 0.36F, glowSize * 0.72F, glowSize * 0.72F, new Vector4i(glowInner, glowInner, glowInner, glowInner), depth);
        Render3DUtil.drawTexture(entry, captureId, -size / 2, -size / 2, size, size, new Vector4i(core, core, core, core), depth);
        float hotSize = size * 0.4F;
        Render3DUtil.drawTexture(entry, bloom, -hotSize / 2, -hotSize / 2, hotSize, hotSize, new Vector4i(hot, hot, hot, hot), depth);
        matrix.pop();
    }

    private static int boost(int color, float factor) {
        int a = (color >> 24) & 255;
        int r = Math.min(255, Math.round(((color >> 16) & 255) * factor));
        int g = Math.min(255, Math.round(((color >> 8) & 255) * factor));
        int b = Math.min(255, Math.round((color & 255) * factor));
        return (a << 24) | (r << 16) | (g << 8) | b;
    }

    public static void drawCube(LivingEntity lastTarget, float anim, float red) {
        float size = 2.2F - anim;
        Camera camera = mc.getEntityRenderDispatcher().camera;
        Vec3d vec = MathUtil.interpolate(lastTarget).subtract(camera.getCameraPos());
        MatrixStack matrix = new MatrixStack();
        matrix.push();
        matrix.multiply(RotationAxis.POSITIVE_X.rotationDegrees(camera.getPitch()));
        matrix.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(camera.getYaw() + 180.0F));
        matrix.translate(vec.x, vec.y + lastTarget.getBoundingBox().getLengthY() / 2, vec.z);
        matrix.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(-camera.getYaw()));
        matrix.multiply(RotationAxis.POSITIVE_X.rotationDegrees(camera.getPitch()));
        matrix.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(MathUtil.interpolate(prevEspValue, espValue)));
        MatrixStack.Entry entry = matrix.peek().copy();
        Render3DUtil.drawTexture(entry, captureId, -size / 2, -size / 2, size, size, ColorUtil.multRedAndAlpha(new Vector4i(ColorUtil.fade(90), ColorUtil.fade(0), ColorUtil.fade(180), ColorUtil.fade(270)), 1 + red * 10, anim), false);
        matrix.pop();
    }

    public static void drawCircle(MatrixStack matrix, LivingEntity lastTarget, float anim, float red, boolean throughWalls, int baseEspColor, float speed, double fixedPhase) {
        MatrixStack worldMatrix = new MatrixStack();
        worldMatrix.multiplyPositionMatrix(lastWorldSpaceMatrix.getPositionMatrix());
        double cs = Double.isNaN(fixedPhase) ? MathUtil.interpolate(circleStep - 0.15F, circleStep) * speed : fixedPhase;
        Vec3d target = getVisualBase(lastTarget);
        boolean depth = !throughWalls;
        EntityDimensions dimensions = getVisualDimensions(lastTarget);
        float width = dimensions.width() * 0.6F;
        float height = dimensions.height();
        GL11.glEnable(GL11.GL_POLYGON_SMOOTH);
        if (depth) {
            GlStateManager._enableDepthTest();
            GlStateManager._depthMask(false);
        } else GlStateManager._disableDepthTest();
        BufferBuilder buffer = tessellator.begin(VertexFormat.DrawMode.TRIANGLE_STRIP, VertexFormats.POSITION_COLOR);
        for (int i = 0, size = 90; i <= size; i++) {
            double yAnim = MathUtil.absSinAnimation(cs) * height;
            double yAnim2 = MathUtil.absSinAnimation(cs - 0.45) * height;
            Vec3d cosSin = MathUtil.cosSin(i, size, width);
            Vec3d nextCosSin = MathUtil.cosSin(i + 1, size, width);
            int saturated = boost(ColorUtil.multRed(baseEspColor, 1 + red * 10), 1.32F);
            float pulse = 0.85F + 0.15F * (float) Math.sin(System.currentTimeMillis() * 0.0045F);
            int curtain = ColorUtil.multAlpha(saturated, 0.6F * anim);
            int glowColor = ColorUtil.multAlpha(saturated, anim * 0.2F * pulse);
            int mainColor = ColorUtil.multAlpha(ColorUtil.overCol(saturated, ColorUtil.WHITE, 0.2F), anim);
            Render3DUtil.vertexLine(worldMatrix, buffer, target.add(cosSin.x, cosSin.y + yAnim, cosSin.z), target.add(cosSin.x, cosSin.y + yAnim2, cosSin.z), curtain, ColorUtil.multAlpha(saturated, 0));
            Render3DUtil.drawLine(target.add(cosSin.x, cosSin.y + yAnim, cosSin.z), target.add(nextCosSin.x, nextCosSin.y + yAnim, nextCosSin.z), glowColor, 7.0F, depth);
            Render3DUtil.drawLine(target.add(cosSin.x, cosSin.y + yAnim, cosSin.z), target.add(nextCosSin.x, nextCosSin.y + yAnim, nextCosSin.z), mainColor, 3, depth);
        }
        net.minecraft.client.render.RenderLayer layer = ru.zov.common.util.render.RenderCompat.getCustomLayer("arizona_triangle_strip", net.minecraft.util.Identifier.of("minecraft", "core/position_color"), VertexFormats.POSITION_COLOR, VertexFormat.DrawMode.TRIANGLE_STRIP, ru.zov.common.util.render.RenderCompat.PipelineSettings.gui());
        ru.zov.common.util.render.RenderCompat.drawCustom(buffer.end(), layer, null);
        if (depth) {
            GlStateManager._depthMask(true);
            GlStateManager._disableDepthTest();
        } else GlStateManager._enableDepthTest();
        GL11.glDisable(GL11.GL_POLYGON_SMOOTH);
    }

    public static void drawCircle(MatrixStack matrix, LivingEntity lastTarget, float anim, float red, boolean throughWalls, int baseEspColor, double fixedPhase) {
        drawCircle(matrix, lastTarget, anim, red, throughWalls, baseEspColor, 1.0F, fixedPhase);
    }

    public static void drawCircle(MatrixStack matrix, LivingEntity lastTarget, float anim, float red) {
        double cs = MathUtil.interpolate(circleStep - 0.15F, circleStep);
        Vec3d target = MathUtil.interpolate(lastTarget);
        boolean canSee = Objects.requireNonNull(mc.player).canSee(lastTarget);
        GL11.glEnable(GL11.GL_POLYGON_SMOOTH);
        if (canSee) {
            GlStateManager._enableDepthTest();
            GlStateManager._depthMask(false);
        } else GlStateManager._disableDepthTest();
        GlStateManager._enableBlend();
        GlStateManager._disableCull();
        GlStateManager._blendFuncSeparate(770, 771, 1, 0);
        BufferBuilder buffer = tessellator.begin(VertexFormat.DrawMode.TRIANGLE_STRIP, VertexFormats.POSITION_COLOR);
        for (int i = 0, size = 90; i <= size; i++) {
            float width = lastTarget.getWidth() * 0.9F;
            float height = lastTarget.getHeight();
            double yAnim = MathUtil.absSinAnimation(cs) * height;
            double yAnim2 = MathUtil.absSinAnimation(cs - 0.45) * height;
            Vec3d cosSin = MathUtil.cosSin(i, size, width);
            Vec3d nextCosSin = MathUtil.cosSin(i + 1, size, width);
            int color = ColorUtil.multRed(ColorUtil.fade(i * 4), 1 + red * 10);
            Render3DUtil.vertexLine(matrix, buffer, target.add(cosSin.x, cosSin.y + yAnim, cosSin.z), target.add(cosSin.x, cosSin.y + yAnim2, cosSin.z), ColorUtil.multAlpha(color, 0.6F * anim), ColorUtil.multAlpha(color, 0));
            Render3DUtil.drawLine(target.add(cosSin.x, cosSin.y + yAnim, cosSin.z), target.add(nextCosSin.x, nextCosSin.y + yAnim, nextCosSin.z), ColorUtil.multAlpha(color, anim), 3, canSee);
        }
        net.minecraft.client.render.RenderLayer layer = ru.zov.common.util.render.RenderCompat.getCustomLayer("arizona_triangle_strip_2", net.minecraft.util.Identifier.of("minecraft", "core/position_color"), VertexFormats.POSITION_COLOR, VertexFormat.DrawMode.TRIANGLE_STRIP, ru.zov.common.util.render.RenderCompat.PipelineSettings.gui());
        ru.zov.common.util.render.RenderCompat.drawCustom(buffer.end(), layer, null);
        if (canSee) {
            GlStateManager._depthMask(true);
            GlStateManager._disableDepthTest();
        } else GlStateManager._enableDepthTest();
        GL11.glDisable(GL11.GL_POLYGON_SMOOTH);
    }

