    public static void drawRadius(Vec3d center, float radius, float width, int color) {
        Vec3d previous = center.add(radius, 0.0F, 0.0F);
        for (int i = 1; i <= 64; i++) {
            Vec3d next = center.add(MathUtil.cosSin(i, 64, radius).x, 0.0F, MathUtil.cosSin(i, 64, radius).z);
            drawLine(previous, next, color, width, false);
            previous = next;
        }
    }

