    public static void drawGhosts(LivingEntity lastTarget, float anim, float red, float speed, int length, boolean throughWalls, int baseEspColor) {
        Camera camera = mc.getEntityRenderDispatcher().camera;
        Vec3d vec = getVisualBase(lastTarget);
        boolean depth = !throughWalls;
        double iAge = MathUtil.interpolate(mc.player.age - 1, mc.player.age);
        EntityDimensions dimensions = getVisualDimensions(lastTarget);
        float halfHeight = dimensions.height() / 2.0F;
        float width = dimensions.width() * 0.72F;
        int ghostLength = Math.max(1, length);
        for (int j = 0; j < 3; j++) {
            for (int i = 0; i <= ghostLength; i++) {
                double radians = Math.toRadians(((i / 2.0F + iAge * speed) * ghostLength + (j * 120)) % (ghostLength * 360));
                double sinQuad = Math.sin(Math.toRadians(iAge * 2.5F * speed + i * halfHeight) * 2) / 2 * 1.18F;
                float offset = ((float) (i + ghostLength) / (ghostLength + ghostLength));
                MatrixStack matrices = new MatrixStack();
                matrices.multiplyPositionMatrix(lastWorldSpaceMatrix.getPositionMatrix());
                matrices.translate(vec.x + Math.cos(radians) * width, (vec.y + halfHeight + sinQuad), vec.z + Math.sin(radians) * width);
                matrices.multiply(camera.getRotation());
                MatrixStack.Entry entry = matrices.peek().copy();
                int saturated = boost(ColorUtil.multRed(baseEspColor, 1 + red * 10), 1.32F);
                float pulse = 0.85F + 0.15F * (float) Math.sin(System.currentTimeMillis() * 0.0045F);
                int core = ColorUtil.multAlpha(saturated, offset * anim);
                int glow = ColorUtil.multAlpha(saturated, offset * anim * 0.26F * pulse);
                int hot = ColorUtil.multAlpha(ColorUtil.overCol(saturated, ColorUtil.WHITE, 0.5F), offset * anim * 0.4F * pulse);
                float scale = 0.5F * offset;
                Render3DUtil.drawTexture(entry, bloom, -scale * 0.65F, -scale * 0.65F, scale * 1.3F, scale * 1.3F, new Vector4i(glow, glow, glow, glow), depth);
                Render3DUtil.drawTexture(entry, bloom, -scale / 2, -scale / 2, scale, scale, new Vector4i(core, core, core, core), depth);
                float hs = scale * 0.42F;
                Render3DUtil.drawTexture(entry, bloom, -hs / 2, -hs / 2, hs, hs, new Vector4i(hot, hot, hot, hot), depth);
            }
        }
    }

