    private static Vec3d getInterpolatedBoxBase(LivingEntity entity) {
        return MathUtil.interpolate(entity);
    }

    private static Vec3d getInterpolatedBoxCenter(LivingEntity entity) {
        Vec3d base = getInterpolatedBoxBase(entity);
        return base.add(0.0, getVisualDimensions(entity).height() * 0.5, 0.0);
    }

    private static Vec3d getVisualBase(LivingEntity entity) {
        return getInterpolatedBoxBase(entity);
    }

    private static EntityDimensions getVisualDimensions(LivingEntity entity) {
        EntityDimensions dimensions = entity.getDimensions(EntityPose.STANDING);
        if (dimensions.height() <= 0.0F || dimensions.width() <= 0.0F) {
            dimensions = entity.getDimensions(entity.getPose());
        }
        return dimensions;
    }

    public static void drawBoxWithShader(Box box, int color, boolean fill, boolean depth, String shaderName) {
        box = box.expand(0.001);
        double x1 = box.minX;
        double y1 = box.minY;
        double z1 = box.minZ;
        double x2 = box.maxX;
        double y2 = box.maxY;
        double z2 = box.maxZ;
        if (fill) {
            ShaderQuad quad = new ShaderQuad(new Vec3d(x1, y1, z1), new Vec3d(x2, y1, z1), new Vec3d(x2, y1, z2), new Vec3d(x1, y1, z2), new Vec3d(x1, y1, z1), new Vec3d(x1, y2, z1), new Vec3d(x2, y2, z1), new Vec3d(x2, y1, z1), new Vec3d(x2, y1, z1), new Vec3d(x2, y2, z1), new Vec3d(x2, y2, z2), new Vec3d(x2, y1, z2), new Vec3d(x1, y1, z2), new Vec3d(x2, y1, z2), new Vec3d(x2, y2, z2), new Vec3d(x1, y2, z2), new Vec3d(x1, y1, z1), new Vec3d(x1, y1, z2), new Vec3d(x1, y2, z2), new Vec3d(x1, y2, z1), new Vec3d(x1, y2, z1), new Vec3d(x1, y2, z2), new Vec3d(x2, y2, z2), new Vec3d(x2, y2, z1), color, depth, shaderName);
            if (depth) SHADER_QUAD_DEPTH.computeIfAbsent(shaderName, k -> new ArrayList<>()).add(quad);
             else SHADER_QUAD.computeIfAbsent(shaderName, k -> new ArrayList<>()).add(quad);
        }
    }


